/// <summary>
/// One search hit. Kind is PO, TO or JOURNAL; Match is ORDER when the query was the record's own number, ITEM when the record holds the searched item. Direction is IN or OUT for orders.
/// </summary>
[DataContractAttribute]
class HSMobileOpsSearchHitRow
{
    str        kind;
    str        match;
    str        reference;
    str        title;
    str        detail;
    str        status;
    str        hitDate;
    real       quantity;
    str        unitId;
    str        direction;
}

Method.Source:
[DataMemberAttribute('Kind')]
public str parmKind(str _value = kind)
{
    kind = _value;
    return kind;
}

[DataMemberAttribute('Match')]
public str parmMatch(str _value = match)
{
    match = _value;
    return match;
}

[DataMemberAttribute('Reference')]
public str parmReference(str _value = reference)
{
    reference = _value;
    return reference;
}

[DataMemberAttribute('Title')]
public str parmTitle(str _value = title)
{
    title = _value;
    return title;
}

[DataMemberAttribute('Detail')]
public str parmDetail(str _value = detail)
{
    detail = _value;
    return detail;
}

[DataMemberAttribute('Status')]
public str parmStatus(str _value = status)
{
    status = _value;
    return status;
}

[DataMemberAttribute('Date')]
public str parmDate(str _value = hitDate)
{
    hitDate = _value;
    return hitDate;
}

[DataMemberAttribute('Quantity')]
public real parmQuantity(real _value = quantity)
{
    quantity = _value;
    return quantity;
}

[DataMemberAttribute('UnitId')]
public str parmUnitId(str _value = unitId)
{
    unitId = _value;
    return unitId;
}

[DataMemberAttribute('Direction')]
public str parmDirection(str _value = direction)
{
    direction = _value;
    return direction;
}
